function [rv, vval, vrate] = loop_rate_violation(vval, vrate, nv)
%LOOP_RATE_VIOLATION  The rate-stability violation of an iteration: the sum, over its options in the loop's order and each option's
%   violations in order (vval, those of a rate-stability metric flagged vrate), of each capped at 10.
%   length: 16
%   vval: inout real[1][*] (passed a plain number)
%   vrate: inout int[*] (passed a whole number)
%   nv: int (passed a whole number)
%   returns rv: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    rv = 0;
    rv = 0;
    for i = (0):((asils.pc.fmin(nv, numel(vval))) - 1)
        if (vrate((i) + 1) == 1)
            rv = (rv + asils.pc.fmin(vval((i) + 1), 10));
        end
    end
end
